/**
 * P0-07 + P1-03 + P1-06: Generate Outbox Key and prepare message envelope
 * P1-06: Propagate correlation_id for end-to-end tracing
 */
const crypto = require('crypto');
const payload = $json;
const timestamp = new Date().toISOString();

// P1-06: Get correlation_id from CORE
const correlationId = payload._timing?.correlation_id || payload.correlation_id || crypto.randomUUID();

// P1-03: Check if async mode is enabled
const asyncEnabled = (($env.OUTBOX_ASYNC_ENABLED || 'false').toString().toLowerCase() === 'true');

const outboxMsgId = payload.outboxMsgId || payload.msgId || crypto.randomUUID();
const outboxKey = `ralphe:outbox:ig:${outboxMsgId}`;
const outboxTtl = parseInt($env.OUTBOX_REDIS_TTL_SEC || '604800', 10);

const outboxEntry = {
  channel: 'instagram',
  correlation_id: correlationId,
  outboxMsgId,
  outboxKey,
  createdAt: timestamp,
  payload: {
    userId: payload.userId,
    restaurantId: payload.restaurantId,
    replyText: payload.replyText,
    buttons: payload.buttons,
    attachments: payload.attachments
  },
  status: 'pending',
  attempts: 0
};

return [{
  json: {
    ...payload,
    _timing: { ...payload._timing, correlation_id: correlationId },
    _outbox: {
      key: outboxKey,
      msgId: outboxMsgId,
      ttl: outboxTtl,
      entry: JSON.stringify(outboxEntry),
      asyncEnabled,
      correlation_id: correlationId
    }
  }
}];

/**
 * W6 - Instagram DM Sender (Meta Graph API)
 * STRAPI GOD MODE: Config reads from _strapiConfig first, $env fallback
 */
const payload = $json;
const timestamp = new Date().toISOString();
const cfg = payload._strapiConfig || {};

const graphVersion = (cfg.graph_api_version || $env.GRAPH_API_VERSION || 'v21.0').toString().trim();
const sendUrl = (cfg.ig_send_url || $env.IG_SEND_URL || '').toString().trim();
const pageId = (cfg.ig_page_id || $env.IG_PAGE_ID || '').toString().trim();
const token = (cfg.ig_api_token || $env.IG_API_TOKEN || '').toString().trim();
const maxRetries = parseInt($env.OUTBOX_MAX_ATTEMPTS || '3', 10);
const baseDelay = parseInt($env.OUTBOX_BASE_DELAY_SEC || '1', 10) * 1000;
const maxDelay = parseInt($env.OUTBOX_MAX_DELAY_SEC || '60', 10) * 1000;

const isMetaApi = sendUrl.includes('graph.facebook.com') || !!pageId;
let url = sendUrl;
if (!url && pageId) { url = `https://graph.facebook.com/${graphVersion}/${pageId}/messages`; }
if (!url) { return [{ json: { ...payload, sent: false, error: 'IG_SEND_URL_NOT_SET', timestamp }}]; }
if (!token) { return [{ json: { ...payload, sent: false, error: 'IG_API_TOKEN_NOT_SET', timestamp }}]; }

const recipientId = (payload.userId || '').toString().trim();
if (!recipientId) { return [{ json: { ...payload, sent: false, error: 'RECIPIENT_MISSING', timestamp }}]; }

let body;
if (isMetaApi) {
  const text = (payload.replyText || '').toString().trim();
  if (Array.isArray(payload.buttons) && payload.buttons.length > 0) {
    body = { recipient: { id: recipientId }, message: { text: text || 'Choose an option:', quick_replies: payload.buttons.slice(0, 13).map((btn, i) => ({ content_type: 'text', title: (btn.title || btn.label || '').slice(0, 20), payload: btn.id || `btn_${i}` })) } };
  } else {
    body = { recipient: { id: recipientId }, message: { text: text || '(empty message)' } };
  }
} else {
  body = { channel: 'instagram', to: recipientId, restaurantId: payload.restaurantId || '', text: payload.replyText || '', buttons: Array.isArray(payload.buttons) ? payload.buttons : [], attachments: Array.isArray(payload.attachments) ? payload.attachments : [] };
}

let lastError = null; let response = null; let finalAttempt = 0;
for (let attempt = 1; attempt <= maxRetries; attempt++) {
  finalAttempt = attempt;
  try {
    response = await $httpRequest({ method: 'POST', url, headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' }, body, json: true, timeout: 30000, returnFullResponse: true });
    const sc = response.statusCode || response.status || 200;
    if (sc >= 200 && sc < 300) { const rb = response.body || response.data || response; return [{ json: { ...payload, sent: true, provider: isMetaApi ? 'meta_ig_api' : 'mock', messageId: rb?.message_id || null, recipient: recipientId, timestamp, attempt: finalAttempt, response: rb }}]; }
    if (sc === 429) { lastError = { statusCode: sc, error: 'RATE_LIMITED' }; if (attempt < maxRetries) { await new Promise(r => setTimeout(r, Math.min(60000, maxDelay))); continue; } }
    if (sc >= 500) { lastError = { statusCode: sc, error: 'SERVER_ERROR' }; if (attempt < maxRetries) { await new Promise(r => setTimeout(r, Math.min(baseDelay * Math.pow(2, attempt-1), maxDelay))); continue; } }
    if (sc >= 400) { return [{ json: { ...payload, sent: false, error: 'CLIENT_ERROR', statusCode: sc, timestamp }}]; }
  } catch (err) {
    lastError = { error: 'REQUEST_FAILED', message: err.message };
    if (attempt < maxRetries) { await new Promise(r => setTimeout(r, Math.min(baseDelay * Math.pow(2, attempt-1), maxDelay))); continue; }
  }
}
return [{ json: { ...payload, sent: false, error: 'MAX_RETRIES_EXHAUSTED', lastError, timestamp, attempts: maxRetries }}];

/**
 * P0-07: Prepare DLQ entry for failed message
 */
const payload = $json;
const timestamp = new Date().toISOString();

const dlqEntry = {
  channel: 'instagram',
  outboxMsgId: payload._outbox?.msgId,
  outboxKey: payload._outbox?.key,
  failedAt: timestamp,
  error: payload.error,
  lastError: payload.lastError,
  statusCode: payload.statusCode,
  attempts: payload.attempts || payload.attempt || 1,
  payload: {
    userId: payload.userId,
    restaurantId: payload.restaurantId,
    replyText: payload.replyText,
    buttons: payload.buttons
  },
  requestBody: payload.requestBody,
  response: payload.response
};

return [{
  json: {
    ...payload,
    _dlq: {
      entry: JSON.stringify(dlqEntry)
    }
  }
}];

// P0-07: Final result node
const payload = $json;
return [{ json: {
  sent: payload.sent,
  messageId: payload.messageId || null,
  recipient: payload.recipient || payload.userId,
  channel: 'instagram',
  outboxMsgId: payload._outbox?.msgId,
  error: payload.error || null,
  timestamp: new Date().toISOString()
}}];

// P0-07: Final result node (DLQ path)
const payload = $json;
return [{ json: {
  sent: false,
  messageId: null,
  recipient: payload.userId,
  channel: 'instagram',
  outboxMsgId: payload._outbox?.msgId,
  error: payload.error,
  dlqPushed: true,
  timestamp: new Date().toISOString()
}}];

// P1-03: Async mode - message queued for worker
const payload = $json;
return [{ json: {
  queued: true,
  sent: null,
  messageId: null,
  recipient: payload.userId,
  channel: 'instagram',
  outboxMsgId: payload._outbox?.msgId,
  mode: 'async',
  timestamp: new Date().toISOString()
}}];
